insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','Before working on a light fixture, what must you do?','Antes de trabajar en una lámpara, ¿qué debes hacer?','["Just flip the wall switch", "Turn off the breaker, lock/tag it, and test that it''s dead", "Wear gloves only", "Work fast"]'::jsonb,'["Solo apagar el apagador", "Bajar el breaker, bloquear/etiquetar y probar que no hay corriente", "Solo usar guantes", "Trabajar rápido"]'::jsonb,1,'OSHA lockout/tagout and electrical safety: verify de-energized.','OSHA: bloqueo/etiquetado y verificar sin energía.','https://www.osha.gov/control-hazardous-energy',array['maintenance']::text[],'role','easy',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','What does a GFCI outlet do?','¿Qué hace un contacto GFCI?','["Saves energy", "Cuts power fast when current leaks to ground, preventing shock", "Only works outdoors", "Makes power stronger"]'::jsonb,'["Ahorra energía", "Corta la corriente rápido si hay fuga a tierra, evitando toques", "Solo sirve afuera", "Da más corriente"]'::jsonb,1,'OSHA: GFCIs protect against ground-fault shock.','OSHA: el GFCI protege contra descargas.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','med',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','Where are GFCI outlets most important in a hotel?','¿Dónde son más importantes los GFCI en un hotel?','["Closets", "Elevators only", "Hallway ceilings", "Near water: bathrooms, kitchen, pool, outdoors"]'::jsonb,'["Clósets", "Solo elevadores", "Techos de pasillo", "Cerca de agua: baños, cocina, alberca, exteriores"]'::jsonb,3,'Wet locations need ground-fault protection.','Los lugares húmedos necesitan protección.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','med',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','A guest-room outlet is warm and discolored. What do you do?','Un contacto del cuarto está caliente y manchado. ¿Qué haces?','["Take it out of service and repair/replace it right away", "Put tape on it", "Plug in less", "Leave it"]'::jsonb,'["Sacarlo de servicio y repararlo de inmediato", "Ponerle cinta", "Conectar menos", "Dejarlo"]'::jsonb,0,'Heat and discoloration signal a fire risk.','El calor y la mancha indican riesgo de incendio.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','easy',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','An extension cord is used as permanent wiring in an office. Is that OK under OSHA?','Una extensión se usa como cableado permanente en una oficina. ¿Lo permite OSHA?','["Only for 1 year", "Yes", "Yes, if it''s orange", "No — flexible cords can''t replace permanent wiring"]'::jsonb,'["Solo por un año", "Sí", "Sí, si es naranja", "No; las extensiones no sustituyen el cableado fijo"]'::jsonb,3,'OSHA 1910.305: flexible cords not a substitute for fixed wiring.','OSHA 1910.305.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','hard',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladders','How should you face a ladder while climbing?','¿Cómo debes estar frente a la escalera al subir?','["Jumping the last steps", "Facing the ladder, keeping 3 points of contact", "Carrying tools in both hands", "Facing away"]'::jsonb,'["Saltando los últimos peldaños", "De frente, con 3 puntos de apoyo", "Con herramientas en ambas manos", "De espaldas"]'::jsonb,1,'OSHA ladder safety: face the ladder, 3 points of contact.','OSHA: de frente y 3 puntos de apoyo.','https://www.osha.gov/ladders',array['maintenance']::text[],'role','easy',array['ladders','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladders','Which step of a stepladder should you never stand on?','¿En qué peldaño de la escalera de tijera nunca te paras?','["The middle step", "Any step is fine", "The bottom step", "The top step or top cap"]'::jsonb,'["El de en medio", "Cualquiera", "El de abajo", "El último peldaño o la tapa"]'::jsonb,3,'OSHA/labels prohibit standing on the top cap and top step.','OSHA y las etiquetas lo prohíben.','https://www.osha.gov/ladders',array['maintenance']::text[],'role','med',array['ladders','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladders','An extension ladder should extend how far above the landing?','¿Cuánto debe sobresalir una escalera de extensión del borde de apoyo?','["10 feet", "3 feet", "6 inches", "It shouldn''t"]'::jsonb,'["10 pies", "3 pies", "6 pulgadas", "No debe"]'::jsonb,1,'OSHA 1926.1053: 3 ft above the upper landing.','OSHA 1926.1053: 3 pies.','https://www.osha.gov/ladders',array['maintenance']::text[],'role','hard',array['ladders','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladders','Ladder angle rule: for every 4 feet up, the base should be how far out?','Regla del ángulo: por cada 4 pies de altura, ¿qué tan lejos va la base?','["4 feet", "3 feet", "1 foot", "Right against the wall"]'::jsonb,'["4 pies", "3 pies", "1 pie", "Pegada a la pared"]'::jsonb,2,'The 4-to-1 rule from OSHA.','La regla 4 a 1 de OSHA.','https://www.osha.gov/ladders',array['maintenance']::text[],'role','med',array['ladders','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','roof','Working near an unguarded roof edge, what''s needed?','Trabajando cerca de una orilla de techo sin barandal, ¿qué se necesita?','["Fall protection per OSHA (guardrail, harness, or warning line as required)", "Sunglasses", "A spotter only", "Nothing if you''re careful"]'::jsonb,'["Protección contra caídas según OSHA (barandal, arnés, o línea de aviso)", "Lentes oscuros", "Solo alguien mirando", "Nada si tienes cuidado"]'::jsonb,0,'OSHA fall protection rules.','Reglas de OSHA contra caídas.','https://www.osha.gov/fall-protection',array['maintenance']::text[],'role','med',array['roof','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','co','A guest room CO alarm goes off. What first?','Suena la alarma de monóxido en un cuarto. ¿Primero qué?','["Open the window and stay", "Silence it and leave", "Get people out to fresh air and call 911", "Replace the battery"]'::jsonb,'["Abrir la ventana y quedarte", "Apagarla e irte", "Sacar a la gente al aire libre y llamar al 911", "Cambiar la pila"]'::jsonb,2,'CDC: CO is deadly; evacuate and call 911.','CDC: el CO es mortal; evacua y llama al 911.','https://www.cdc.gov/carbon-monoxide/about/index.html',array['maintenance']::text[],'role','easy',array['co','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','co','Why must boiler and heater flues be inspected?','¿Por qué revisar los ductos de calderas y calentadores?','["A blocked or leaking vent can push CO into the building", "They make noise", "No reason", "For looks"]'::jsonb,'["Un ducto tapado o con fuga puede meter CO al edificio", "Hacen ruido", "Por nada", "Por estética"]'::jsonb,0,'CDC: have fuel-burning systems serviced yearly.','CDC: revisión anual.','https://www.cdc.gov/carbon-monoxide/about/index.html',array['maintenance']::text[],'role','med',array['co','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','legionella','Why flush little-used guest showers regularly?','¿Por qué abrir seguido las regaderas poco usadas?','["To save water", "No reason", "To test pressure only", "Stagnant water can grow Legionella"]'::jsonb,'["Para ahorrar", "Por nada", "Solo para probar presión", "El agua estancada puede generar Legionella"]'::jsonb,3,'CDC: stagnant water and lukewarm temps help Legionella grow.','CDC: agua estancada y tibia favorece la Legionella.','https://www.cdc.gov/legionella/about/index.html',array['maintenance']::text[],'role','med',array['legionella','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','legionella','Legionella grows best in water at roughly what temperature?','¿A qué temperatura crece mejor la Legionella?','["Below 40°F", "Above 160°F", "77–113°F (25–45°C)", "Only at freezing"]'::jsonb,'["Menos de 40°F", "Más de 160°F", "77–113°F (25–45°C)", "Solo congelada"]'::jsonb,2,'CDC: grows best 77–113°F.','CDC: 77–113°F.','https://www.cdc.gov/legionella/about/index.html',array['maintenance']::text[],'role','hard',array['legionella','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','legionella','Which hotel feature is a known Legionella risk?','¿Qué parte del hotel es riesgo conocido de Legionella?','["Carpet", "Window blinds", "Hot tubs", "Pillows"]'::jsonb,'["Alfombra", "Persianas", "Jacuzzis", "Almohadas"]'::jsonb,2,'CDC lists hot tubs, cooling towers and plumbing.','CDC: jacuzzis, torres de enfriamiento y tuberías.','https://www.cdc.gov/legionella/about/index.html',array['maintenance']::text[],'role','med',array['legionella','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','Minnesota requires pool operators to test chlorine and pH how often?','¿Cada cuánto exige Minnesota medir cloro y pH de la alberca?','["Never", "Only when cloudy", "Several times a day per MDH rules, and log it", "Once a month"]'::jsonb,'["Nunca", "Solo si está turbia", "Varias veces al día según MDH, y registrarlo", "Una vez al mes"]'::jsonb,2,'MDH pool rules require frequent tests and records.','MDH exige pruebas frecuentes y registro.','https://www.health.state.mn.us/communities/environment/pools/',array['maintenance']::text[],'role','med',array['pool','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','What''s the ideal pool pH range?','¿Cuál es el rango ideal de pH de la alberca?','["4.0–5.0", "About 7.2–7.8", "Any", "9.0–10.0"]'::jsonb,'["4.0–5.0", "Aprox. 7.2–7.8", "Cualquiera", "9.0–10.0"]'::jsonb,1,'CDC/MDH: pH 7.2–7.8.','CDC/MDH: pH 7.2–7.8.','https://www.cdc.gov/healthy-swimming/about/index.html',array['maintenance']::text[],'role','hard',array['pool','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','A guest has a diarrhea accident in the pool. What happens?','Un huésped tiene un accidente de diarrea en la alberca. ¿Qué pasa?','["Nothing", "Scoop it and reopen", "Add perfume", "Close the pool and follow the CDC fecal-incident hyperchlorination steps"]'::jsonb,'["Nada", "Sacarlo y reabrir", "Echar perfume", "Cerrar la alberca y seguir los pasos de supercloración de CDC"]'::jsonb,3,'CDC fecal incident guidance.','Guía de CDC.','https://www.cdc.gov/healthy-swimming/media/pdfs/fecal-incident-response-guidelines.pdf',array['maintenance']::text[],'role','med',array['pool','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','Why must the pool drain cover be intact?','¿Por qué la tapa del desagüe debe estar completa?','["It looks better", "A broken cover can trap a swimmer (entrapment)", "It''s optional", "It filters leaves"]'::jsonb,'["Se ve mejor", "Una tapa rota puede atrapar a un nadador", "Es opcional", "Filtra hojas"]'::jsonb,1,'Federal VGB Act requires compliant drain covers.','La ley VGB exige tapas seguras.','https://www.cpsc.gov/Business--Manufacturing/Business-Education/Pool-and-Spa-Safety',array['maintenance']::text[],'role','med',array['pool','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','Why keep 18 inches clear below sprinkler heads?','¿Por qué dejar 18 pulgadas libres bajo los rociadores?','["No reason", "For Wi-Fi", "So water can spray properly", "For looks"]'::jsonb,'["Por nada", "Por el Wi-Fi", "Para que el agua se rocíe bien", "Por estética"]'::jsonb,2,'NFPA 13 clearance rule.','NFPA 13.','https://www.nfpa.org/codes-and-standards/nfpa-13-standard-development/13',array['maintenance']::text[],'role','med',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','Can you hang things from a sprinkler head?','¿Puedes colgar cosas de un rociador?','["Only hangers", "Only in storage", "Yes, light items", "Never"]'::jsonb,'["Solo ganchos", "Solo en bodega", "Sí, ligeras", "Nunca"]'::jsonb,3,'It can trigger or block the sprinkler.','Puede activarlo o bloquearlo.','https://www.nfpa.org/codes-and-standards/nfpa-25-standard-development/25',array['maintenance']::text[],'role','easy',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','A fire alarm panel shows ''trouble''. What does that usually mean?','El panel de alarma marca ''trouble''. ¿Qué suele significar?','["All clear", "A drill", "A fault in the system (power, wiring, device) that must be fixed — not a fire", "A fire"]'::jsonb,'["Todo bien", "Simulacro", "Una falla del sistema que hay que arreglar; no es incendio", "Un incendio"]'::jsonb,2,'Trouble signals need prompt service; the system may not work.','La señal de falla requiere servicio pronto.','https://www.nfpa.org/codes-and-standards/nfpa-72-standard-development/72',array['maintenance']::text[],'role','hard',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','Before testing the fire alarm, who must be notified?','Antes de probar la alarma, ¿a quién avisas?','["Only the GM''s family", "The monitoring company and the front desk/staff", "Only guests", "Nobody"]'::jsonb,'["Solo la familia del gerente", "A la empresa de monitoreo y a recepción y personal", "Solo huéspedes", "A nadie"]'::jsonb,1,'Avoid false dispatch and panic.','Evita envíos falsos y pánico.','general hospitality best practice',array['maintenance']::text[],'role','med',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hvac','A PTAC is dripping water inside the room. Likely cause?','Un PTAC gotea dentro del cuarto. ¿Causa probable?','["The phone", "The TV", "Blocked condensate drain or unit not tilted to drain outside", "Too much electricity"]'::jsonb,'["El teléfono", "La tele", "Drenaje de condensado tapado o mal nivelado", "Mucha electricidad"]'::jsonb,2,'Condensate must drain outside.','El condensado debe salir afuera.','general hospitality best practice',array['maintenance']::text[],'role','med',array['hvac','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','refrigerant','Who may legally work on sealed refrigerant systems?','¿Quién puede trabajar en sistemas sellados de refrigerante?','["EPA Section 608 certified technicians", "Only the GM", "Anyone with gloves", "Any staff"]'::jsonb,'["Técnicos certificados EPA Sección 608", "Solo el gerente", "Cualquiera con guantes", "Cualquier empleado"]'::jsonb,0,'EPA 608 certification is required.','Se requiere certificación EPA 608.','https://www.epa.gov/section608',array['maintenance']::text[],'role','hard',array['refrigerant','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','water_heater','Why is a water heater set to about 120°F at the taps?','¿Por qué el agua caliente sale a unos 120°F?','["No reason", "To save money only", "Brand rule only", "To reduce scald risk while keeping tanks hot enough for Legionella control"]'::jsonb,'["Por nada", "Solo ahorrar", "Regla de marca", "Para evitar quemaduras manteniendo el tanque caliente contra Legionella"]'::jsonb,3,'Balance scald and Legionella risk (CDC toolkit).','Balance quemadura/Legionella (CDC).','https://www.cdc.gov/legionella/hcp/toolkit/index.html',array['maintenance']::text[],'role','med',array['water_heater','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','water_heater','What does the T&P valve on a water heater do?','¿Qué hace la válvula T&P del calentador?','["Releases water if temperature or pressure is too high", "Measures gas", "Nothing", "Adds heat"]'::jsonb,'["Libera agua si la temperatura o presión es muy alta", "Mide el gas", "Nada", "Da calor"]'::jsonb,0,'It prevents tank explosions; never cap it.','Evita explosiones; nunca la tapes.','https://www.energy.gov/energysaver/storage-water-heaters',array['maintenance']::text[],'role','easy',array['water_heater','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','plumbing','A toilet is overflowing. First move?','Un excusado se desborda. ¿Primero qué?','["Put towels and leave", "Call the guest", "Keep flushing", "Turn off the supply valve behind it"]'::jsonb,'["Poner toallas e irte", "Llamar al huésped", "Seguir jalando", "Cerrar la llave de paso detrás"]'::jsonb,3,'Stop the water first.','Primero cerrar el agua.','general hospitality best practice',array['maintenance']::text[],'role','easy',array['plumbing','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','plumbing','A ceiling stain appears below a room. What do you check?','Aparece una mancha en el techo bajo un cuarto. ¿Qué revisas?','["The elevator", "The room above: tub caulk, toilet seal, supply lines", "The hallway carpet", "The roof only"]'::jsonb,'["El elevador", "El cuarto de arriba: sellador, sello del excusado, mangueras", "La alfombra", "Solo el techo"]'::jsonb,1,'Find and stop the leak source.','Encuentra la fuga.','general hospitality best practice',array['maintenance']::text[],'role','med',array['plumbing','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tools','A power tool''s cord is frayed. What do you do?','El cable de una herramienta está pelado. ¿Qué haces?','["Use it carefully", "Tape it", "Ignore", "Tag it out and repair/replace it"]'::jsonb,'["Usarla con cuidado", "Ponerle cinta", "Ignorar", "Sacarla de servicio y repararla"]'::jsonb,3,'OSHA: damaged tools removed from service.','OSHA: retirar herramientas dañadas.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','easy',array['tools','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ppe','Grinding metal requires which PPE at minimum?','Al esmerilar metal, ¿qué EPP mínimo?','["Safety glasses or face shield", "Gloves only", "None", "Sunglasses"]'::jsonb,'["Lentes de seguridad o careta", "Solo guantes", "Nada", "Lentes oscuros"]'::jsonb,0,'OSHA eye and face protection.','OSHA protección ocular.','https://www.osha.gov/personal-protective-equipment',array['maintenance']::text[],'role','easy',array['ppe','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','preventive','What is preventive maintenance (PM)?','¿Qué es el mantenimiento preventivo?','["Painting once", "Fixing only after complaints", "Scheduled checks and service before things break", "Ordering parts"]'::jsonb,'["Pintar una vez", "Arreglar solo con quejas", "Revisiones programadas antes de que falle", "Pedir piezas"]'::jsonb,2,'PM reduces out-of-order rooms.','Reduce cuartos fuera de servicio.','general hospitality best practice',array['maintenance']::text[],'role','med',array['preventive','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guest_room','You fix something in an occupied room. Before leaving?','Arreglas algo en un cuarto ocupado. ¿Antes de salir?','["Leave tools", "Clean up, test it, and leave the room as you found it; note it in the log", "Use the bathroom", "Take a nap"]'::jsonb,'["Dejar herramientas", "Limpiar, probar y dejarlo como estaba; registrarlo", "Usar el baño", "Dormir"]'::jsonb,1,'Respect the guest''s space.','Respeta el espacio del huésped.','general hospitality best practice',array['maintenance']::text[],'role','med',array['guest_room','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','snow','When should sidewalks and entrances be cleared?','¿Cuándo se limpian banquetas y entradas?','["Only after the storm ends", "Never", "Early and repeatedly during snowfall, before guests and staff arrive", "Once a week"]'::jsonb,'["Solo al terminar", "Nunca", "Temprano y varias veces durante la nevada", "Una vez por semana"]'::jsonb,2,'OSHA winter slip prevention.','OSHA invierno.','https://www.osha.gov/winter-weather',array['maintenance']::text[],'role','med',array['snow','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','snow','Snowblower is jammed. Safe way to clear it?','La quitanieves se atoró. ¿Cómo destaparla?','["Shut it off, wait for parts to stop, and use a clearing tool — never your hands", "Use a broom while running", "Use your hand quickly", "Kick it running"]'::jsonb,'["Apagarla, esperar a que pare y usar herramienta; nunca la mano", "Con escoba prendida", "Con la mano rápido", "Patearla prendida"]'::jsonb,0,'CPSC: snowblower hand injuries are common.','CPSC: lesiones comunes en manos.','https://www.cpsc.gov/Safety-Education/Safety-Guides/Sports-Fitness-and-Recreation/Snow-Throwers',array['maintenance']::text[],'role','hard',array['snow','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','elevator','Someone is stuck in an elevator. What do you do?','Alguien está atrapado en el elevador. ¿Qué haces?','["Reassure them, call the elevator company (and 911 if any emergency); don''t force doors", "Climb in the shaft", "Pry the doors", "Ignore"]'::jsonb,'["Tranquilizarlos y llamar a la empresa (y al 911 si es emergencia); no forzar puertas", "Meterte al cubo", "Forzar puertas", "Ignorar"]'::jsonb,0,'Only trained elevator techs or firefighters do rescues.','Solo técnicos o bomberos rescatan.','general hospitality best practice',array['maintenance']::text[],'role','med',array['elevator','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Hot breakfast items on the buffet must be held at what temperature or above?','¿A qué temperatura mínima se mantienen calientes los alimentos del buffet?','["90°F", "100°F", "135°F", "120°F"]'::jsonb,'["90°F", "100°F", "135°F", "120°F"]'::jsonb,2,'FDA Food Code: hot holding at 135°F or above.','Código FDA: 135°F o más.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','How often should you check buffet temperatures with a thermometer?','¿Cada cuánto revisas temperaturas del buffet con termómetro?','["Once a week", "Only if a guest complains", "Regularly through service (e.g., every 1–2 hours) and log it", "Never"]'::jsonb,'["Una vez a la semana", "Solo con quejas", "Seguido durante el servicio (cada 1–2 horas) y registrarlo", "Nunca"]'::jsonb,2,'Logged checks catch problems early.','El registro detecta problemas a tiempo.','https://www.health.state.mn.us/people/foodsafety/',array['breakfast']::text[],'role','med',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Scrambled eggs on the line read 120°F. What do you do?','Los huevos revueltos marcan 120°F. ¿Qué haces?','["Serve them", "Add salt", "Stir and leave", "Follow the rule: reheat to 165°F if within 2 hours, otherwise throw out"]'::jsonb,'["Servirlos", "Echar sal", "Mover y dejar", "Seguir la regla: recalentar a 165°F si van menos de 2 horas; si no, tirarlos"]'::jsonb,3,'Food Code reheating for hot holding: 165°F.','Recalentar a 165°F.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','hard',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Sausage links (pork) should reach at least what temperature?','¿A qué temperatura mínima debe llegar la salchicha de cerdo?','["110°F", "160°F for ground pork sausage", "100°F", "130°F"]'::jsonb,'["110°F", "160°F para salchicha molida", "100°F", "130°F"]'::jsonb,1,'FoodSafety.gov: ground meats 160°F.','FoodSafety.gov: carnes molidas 160°F.','https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures',array['breakfast']::text[],'role','med',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','thermometer','How do you check a probe thermometer is accurate?','¿Cómo compruebas que el termómetro es exacto?','["Put it in coffee", "Shake it", "Ask a guest", "Ice-water test: it should read 32°F"]'::jsonb,'["Meterlo al café", "Sacudirlo", "Preguntar", "Prueba de agua con hielo: debe marcar 32°F"]'::jsonb,3,'Calibrate in ice water to 32°F.','Calibrar en hielo a 32°F.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['thermometer','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','thermometer','Why sanitize the thermometer probe between foods?','¿Por qué desinfectar el termómetro entre alimentos?','["It''s decoration", "To avoid cross-contamination", "No reason", "It''s faster"]'::jsonb,'["Es adorno", "Para evitar contaminación cruzada", "Por nada", "Es más rápido"]'::jsonb,1,'Clean and sanitize probes between uses.','Limpiar y desinfectar entre usos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['thermometer','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','handwashing','Can you wash hands in the food prep sink?','¿Puedes lavarte las manos en la tarja de preparación?','["Only quickly", "Yes", "No — only at a designated handwashing sink", "Yes, if empty"]'::jsonb,'["Solo rápido", "Sí", "No; solo en el lavamanos designado", "Sí, si está vacía"]'::jsonb,2,'Food Code: use designated handwash sinks only.','Usar solo el lavamanos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['handwashing','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','gloves','Can gloves replace handwashing?','¿Los guantes reemplazan lavarse las manos?','["Only in the morning", "No — wash before putting on gloves and change them often", "Yes", "Yes, if blue"]'::jsonb,'["Solo en la mañana", "No; lávate antes de ponértelos y cámbialos seguido", "Sí", "Sí, si son azules"]'::jsonb,1,'Food Code: wash hands before gloving.','Lavarse antes de los guantes.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['gloves','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','gloves','Ready-to-eat foods like muffins or fruit should be handled with…','Alimentos listos para comer como muffins o fruta se manejan con…','["Your apron", "Bare hands", "Gloves, tongs or deli paper — not bare hands", "A napkin from the guest"]'::jsonb,'["El mandil", "La mano", "Guantes, pinzas o papel; no la mano", "Servilleta del huésped"]'::jsonb,2,'Food Code: no bare-hand contact with RTE foods.','No tocar con la mano alimentos listos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['gloves','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','illness','You have vomiting or diarrhea. Can you work breakfast?','Tienes vómito o diarrea. ¿Puedes trabajar en el desayuno?','["No — tell your manager; you must stay out of food work", "Yes, with gloves", "Only half a shift", "Yes, if you feel OK"]'::jsonb,'["No; avisa al gerente; no puedes manejar alimentos", "Sí, con guantes", "Solo medio turno", "Sí, si te sientes bien"]'::jsonb,0,'Food Code exclusion for vomiting/diarrhea.','Exclusión por vómito o diarrea.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['illness','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','illness','You have a cut on your hand. Before working with food?','Tienes una cortada en la mano. ¿Antes de manejar comida?','["Use tape only", "Work bare-handed", "Leave it open", "Cover it with a bandage and a glove"]'::jsonb,'["Solo cinta", "Trabajar sin guante", "Dejarla abierta", "Cubrirla con curita y guante"]'::jsonb,3,'Food Code: cover wounds with a bandage and glove.','Cubrir con curita y guante.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['illness','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','How many ''major food allergens'' does the FDA list?','¿Cuántos alérgenos principales reconoce la FDA?','["1", "9", "3", "20"]'::jsonb,'["1", "9", "3", "20"]'::jsonb,1,'FDA: milk, eggs, fish, shellfish, tree nuts, peanuts, wheat, soy, sesame.','FDA: leche, huevo, pescado, mariscos, nueces, cacahuate, trigo, soya, ajonjolí.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','easy',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','Which became the 9th major allergen in 2023?','¿Cuál se volvió el 9º alérgeno principal en 2023?','["Corn", "Sesame", "Chocolate", "Strawberries"]'::jsonb,'["Maíz", "Ajonjolí", "Chocolate", "Fresas"]'::jsonb,1,'FASTER Act added sesame (effective Jan 1, 2023).','La ley FASTER agregó el ajonjolí (2023).','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','med',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','A guest asks if the waffles have nuts. You''re not sure. What do you do?','Un huésped pregunta si los waffles tienen nueces. No estás seguro. ¿Qué haces?','["Say no", "Say probably not", "Check the product label/ingredient list and never guess", "Tell them to try a bite"]'::jsonb,'["Decir que no", "Decir que probablemente no", "Revisar la etiqueta e ingredientes; nunca adivinar", "Que pruebe un poco"]'::jsonb,2,'Guessing can cause a serious reaction.','Adivinar puede causar una reacción grave.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','med',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','How do you avoid cross-contact with a peanut butter station?','¿Cómo evitas contacto cruzado con la estación de crema de cacahuate?','["Mix it with jam", "Separate utensils and keep it away from other items", "Share the knife", "Put it by the bread only"]'::jsonb,'["Mezclarla con mermelada", "Utensilios separados y lejos de otros alimentos", "Compartir el cuchillo", "Ponerla junto al pan"]'::jsonb,1,'Separate tools prevent allergen cross-contact.','Utensilios separados evitan contacto cruzado.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','med',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','A guest says their throat is tight after eating. What do you do?','Un huésped dice que se le cierra la garganta tras comer. ¿Qué haces?','["Give water and wait", "Tell them to lie down", "Call 911 right away — possible anaphylaxis; help them use their epinephrine if they have it", "Offer more food"]'::jsonb,'["Dar agua y esperar", "Que se acueste", "Llamar al 911 de inmediato; posible anafilaxia; ayúdale con su epinefrina si la tiene", "Ofrecer más comida"]'::jsonb,2,'Anaphylaxis is life-threatening.','La anafilaxia pone en riesgo la vida.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','hard',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','date_marking','Opened milk or cut fruit held cold: max days before discarding under the Food Code?','Leche abierta o fruta cortada en frío: ¿máximo de días antes de desechar según el Código?','["30 days", "No limit", "1 year", "7 days (day of prep counts as day 1)"]'::jsonb,'["30 días", "Sin límite", "1 año", "7 días (el día de preparación cuenta como día 1)"]'::jsonb,3,'Food Code date marking: 7 days at 41°F or less.','Marcado de fechas: 7 días a 41°F o menos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['date_marking','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','date_marking','Why label containers with prep date?','¿Por qué etiquetar recipientes con la fecha?','["No reason", "So old food is used first or thrown out on time (FIFO)", "Brand rule only", "For decoration"]'::jsonb,'["Por nada", "Para usar primero lo viejo o tirarlo a tiempo (PEPS)", "Solo marca", "Adorno"]'::jsonb,1,'First in, first out.','Primero en entrar, primero en salir.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['date_marking','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','storage','In the fridge, where does raw egg/meat go?','En el refri, ¿dónde va el huevo o carne cruda?','["Bottom shelf, below ready-to-eat foods", "Next to fruit", "Anywhere", "Top shelf"]'::jsonb,'["Abajo, debajo de lo listo para comer", "Junto a la fruta", "Donde sea", "Arriba"]'::jsonb,0,'Prevents drips onto ready-to-eat food.','Evita goteo sobre alimentos listos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['storage','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','storage','Food boxes in storage must be kept…','Las cajas de comida en bodega se guardan…','["In the hallway", "At least 6 inches off the floor", "Next to chemicals", "On the floor"]'::jsonb,'["En el pasillo", "Al menos 6 pulgadas del piso", "Junto a químicos", "En el piso"]'::jsonb,1,'Food Code: store food off the floor.','Guardar arriba del piso.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['storage','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Where should cleaning chemicals be stored?','¿Dónde se guardan los químicos de limpieza?','["In the cereal area", "Below and away from food", "Above the buffet", "On the food shelf"]'::jsonb,'["Con el cereal", "Abajo y lejos de la comida", "Arriba del buffet", "En el estante de comida"]'::jsonb,1,'Food Code: chemicals stored separately below food.','Químicos abajo y separados.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['chemicals','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sanitizer','Why test sanitizer buckets with test strips?','¿Por qué medir los cubetas de sanitizante con tiras?','["They expire", "No reason", "Too weak won''t kill germs; too strong can be toxic", "For color"]'::jsonb,'["Caducan", "Por nada", "Muy débil no mata gérmenes; muy fuerte es tóxico", "Por el color"]'::jsonb,2,'Food Code: sanitizer at label concentration.','Concentración según etiqueta.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['sanitizer','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','waffle','The waffle maker is hot. How do you keep guests safe?','La wafflera está caliente. ¿Cómo cuidas a los huéspedes?','["Keep it clean, posted with instructions, and watch kids near it", "Unplug only on weekends", "Take the sign down", "Let kids use it alone"]'::jsonb,'["Limpia, con instrucciones visibles y vigilando a los niños", "Desconectarla solo fines", "Quitar el letrero", "Dejar que los niños la usen solos"]'::jsonb,0,'Burns are a common buffet injury.','Las quemaduras son comunes.','https://www.mayoclinic.org/first-aid/first-aid-burns/basics/art-20056649',array['breakfast']::text[],'role','easy',array['waffle','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','A guest asks for something not on the buffet (like gluten-free bread). Best response?','Un huésped pide algo que no está (pan sin gluten). ¿Mejor respuesta?','["Tell them to go out", "Check what you have in back and offer options", "Ignore", "Say no"]'::jsonb,'["Que salga a comprar", "Revisar qué hay atrás y ofrecer opciones", "Ignorar", "Decir que no"]'::jsonb,1,'Offer what''s possible.','Ofrece lo posible.','general hospitality best practice',array['breakfast']::text[],'role','easy',array['service','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','The buffet runs out of eggs during the rush. What''s best?','Se acaba el huevo en la hora pico. ¿Qué es lo mejor?','["Serve cold leftovers", "Close breakfast early", "Wait for the end", "Refill fast and tell waiting guests it''s coming in a few minutes"]'::jsonb,'["Servir sobras frías", "Cerrar antes", "Esperar al final", "Rellenar rápido y avisar que ya viene"]'::jsonb,3,'Communicate during delays.','Comunica en las demoras.','general hospitality best practice',array['breakfast']::text[],'role','med',array['service','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','Ten minutes before breakfast ends, a family arrives. What do you do?','Diez minutos antes de cerrar llega una familia. ¿Qué haces?','["Welcome them and keep items available until close", "Start breaking down", "Turn off lights", "Tell them it''s over"]'::jsonb,'["Recibirlos y mantener comida hasta el cierre", "Empezar a recoger", "Apagar luces", "Decir que se acabó"]'::jsonb,0,'Don''t break down early.','No recojas antes.','general hospitality best practice',array['breakfast']::text[],'role','easy',array['service','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','Breakfast tables between guests should be…','Las mesas entre huéspedes se…','["Left for later", "Brushed with a napkin", "Cleared, wiped and sanitized", "Wiped with the floor rag"]'::jsonb,'["Dejan para después", "Sacuden con servilleta", "Levantan, limpian y desinfectan", "Limpian con el trapo del piso"]'::jsonb,2,'Sanitize food-contact and table surfaces.','Desinfectar superficies.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['cleaning','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','Why clean the juice and coffee machine nozzles daily?','¿Por qué limpiar boquillas de jugo y café a diario?','["They taste better hot", "Residue grows mold and bacteria", "For shine", "No reason"]'::jsonb,'["Saben mejor", "Los residuos generan moho y bacterias", "Por brillo", "Por nada"]'::jsonb,1,'Manufacturer cleaning and Food Code.','Limpieza según fabricante.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['cleaning','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pests','You see a mouse dropping in the pantry. What do you do?','Ves excremento de ratón en la bodega. ¿Qué haces?','["Ignore", "Tell your manager right away and don''t use exposed food", "Sweep and forget", "Keep serving"]'::jsonb,'["Ignorar", "Avisar al gerente y no usar comida expuesta", "Barrer y olvidar", "Seguir sirviendo"]'::jsonb,1,'Pest signs require action and pest control.','Las plagas requieren acción.','https://www.health.state.mn.us/people/foodsafety/',array['breakfast']::text[],'role','easy',array['pests','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ice','How should you scoop ice for drinks?','¿Cómo sacas hielo para bebidas?','["With hands", "With a scoop that has a handle — never a glass or hands", "With a cup from the trash", "With a glass"]'::jsonb,'["Con la mano", "Con cuchara con mango; nunca con vaso ni mano", "Con un vaso usado", "Con un vaso"]'::jsonb,1,'Glass can break into ice; hands contaminate.','El vidrio se rompe; las manos contaminan.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['ice','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hair','Why wear a hair restraint at breakfast prep?','¿Por qué usar red o gorra al preparar?','["Fashion", "No reason", "Keeps you warm", "Keeps hair out of food"]'::jsonb,'["Moda", "Por nada", "Calienta", "Evita pelos en la comida"]'::jsonb,3,'Food Code requires hair restraints.','El código lo exige.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['hair','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','jewelry','Which jewelry is allowed when handling food?','¿Qué joya se permite al manejar comida?','["A plain band ring", "Watches", "Many rings", "Bracelets"]'::jsonb,'["Un anillo liso", "Reloj", "Muchos anillos", "Pulseras"]'::jsonb,0,'Food Code: plain ring only on hands/arms.','Solo anillo liso.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['jewelry','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','waste','A guest drops a full tray. First step?','Un huésped tira una charola llena. ¿Primer paso?','["Laugh", "Make them clean it", "Leave it", "Check they''re OK, put out a wet-floor sign, clean it up"]'::jsonb,'["Reírte", "Que él limpie", "Dejarlo", "Ver que esté bien, poner señal y limpiar"]'::jsonb,3,'Safety then cleanup.','Seguridad y limpieza.','https://www.osha.gov/walking-working-surfaces',array['breakfast']::text[],'role','med',array['waste','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bloodborne','You find vomit in a room. How should it be cleaned?','Encuentras vómito en un cuarto. ¿Cómo se limpia?','["Vacuum it", "Wipe with a bath towel and reuse it", "Gloves and PPE, absorb it, clean, then disinfect with an EPA-registered product", "Spray air freshener"]'::jsonb,'["Aspirarlo", "Limpiar con toalla de baño y reusarla", "Con guantes y EPP: absorber, limpiar y desinfectar con producto registrado por EPA", "Echar aromatizante"]'::jsonb,2,'CDC: clean then disinfect body fluids with PPE.','CDC: limpiar y desinfectar con EPP.','https://www.cdc.gov/hygiene/about/when-and-how-to-clean-and-disinfect-a-facility.html',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['bloodborne','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bloodborne','After removing gloves, what do you do?','Después de quitarte los guantes, ¿qué haces?','["Wash your hands", "Wipe on your uniform", "Reuse the gloves", "Nothing"]'::jsonb,'["Lavarte las manos", "Limpiarte en el uniforme", "Reusarlos", "Nada"]'::jsonb,0,'OSHA: wash hands after glove removal.','OSHA: lavarse tras quitarse guantes.','https://www.osha.gov/bloodborne-pathogens',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['bloodborne','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Can you use a cleaner from an unlabeled spray bottle?','¿Puedes usar un limpiador de una botella sin etiqueta?','["Yes, smell it first", "Yes, mix it", "No — report it and get a labeled one", "Yes, if blue"]'::jsonb,'["Sí, olerlo primero", "Sí, mezclarlo", "No; repórtalo y usa una etiquetada", "Sí, si es azul"]'::jsonb,2,'HazCom: containers must be labeled.','HazCom: deben estar etiquetados.','https://www.osha.gov/hazcom',array['hk_supervisor','houseman','room_attendant']::text[],'role','easy',array['chemicals','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','What does a GHS pictogram with a flame mean?','¿Qué significa el pictograma GHS con flama?','["Under pressure", "Safe", "Toxic to fish", "Flammable"]'::jsonb,'["Bajo presión", "Seguro", "Tóxico para peces", "Inflamable"]'::jsonb,3,'OSHA HazCom pictograms.','Pictogramas HazCom.','https://www.osha.gov/hazcom',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['chemicals','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','What does the GHS ''corrosion'' pictogram warn about?','¿De qué advierte el pictograma de ''corrosión''?','["It''s food-safe", "It''s a gas", "It''s flammable", "It can burn skin/eyes or damage metal"]'::jsonb,'["Es apto para comida", "Es gas", "Inflamable", "Puede quemar piel/ojos o dañar metal"]'::jsonb,3,'Corrosives need gloves and eye protection.','Usar guantes y lentes.','https://www.osha.gov/hazcom',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['chemicals','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','How can you reduce back strain making beds?','¿Cómo reduces el esfuerzo de espalda al tender camas?','["Bend your knees, kneel at corners, and avoid twisting", "Bend at the waist all day", "Work faster", "Lift the mattress with your back"]'::jsonb,'["Doblar rodillas, hincarte en esquinas y no girar", "Agacharte de cintura todo el día", "Trabajar más rápido", "Levantar el colchón con la espalda"]'::jsonb,0,'OSHA hotel housekeeping ergonomics.','Ergonomía OSHA.','https://www.osha.gov/ergonomics',array['hk_supervisor','houseman','room_attendant']::text[],'role','easy',array['ergonomics','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','Why push a cart instead of pulling it?','¿Por qué empujar el carro en vez de jalarlo?','["Pushing is easier on your back and you can see ahead", "No difference", "Pulling is safer", "Carts only pull"]'::jsonb,'["Empujar cuida tu espalda y ves adelante", "Igual", "Jalar es más seguro", "Solo se jalan"]'::jsonb,0,'OSHA: pushing reduces strain.','Empujar reduce esfuerzo.','https://www.osha.gov/ergonomics',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['ergonomics','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','A guest is acting aggressively in the hallway. What do you do?','Un huésped actúa agresivo en el pasillo. ¿Qué haces?','["Argue", "Ignore and keep working next to them", "Leave the area, get to a safe place, and call the desk/manager (911 if danger)", "Block their way"]'::jsonb,'["Discutir", "Ignorar y seguir junto a él", "Alejarte, ponerte a salvo y llamar a recepción o gerente (911 si hay peligro)", "Bloquearle el paso"]'::jsonb,2,'Your safety first; report.','Tu seguridad primero.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['safety','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','Many cities and brands give housekeepers safety buttons/devices. When do you use one?','Muchos hoteles dan botones de pánico. ¿Cuándo lo usas?','["Never", "Only for fire", "Only to call for towels", "Whenever you feel threatened or unsafe in a room or hallway"]'::jsonb,'["Nunca", "Solo en incendio", "Solo para pedir toallas", "Siempre que te sientas amenazada o insegura"]'::jsonb,3,'Panic buttons are for any threat.','Para cualquier amenaza.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['safety','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','weapons','You see a gun or drugs in a room. What do you do?','Ves un arma o drogas en un cuarto. ¿Qué haces?','["Don''t touch anything, leave, and tell your manager right away", "Move it to a drawer", "Take a picture and post it", "Keep cleaning"]'::jsonb,'["No tocar nada, salir y avisar de inmediato al gerente", "Guardarlo en un cajón", "Tomar foto y publicarla", "Seguir limpiando"]'::jsonb,0,'Leave it for management/police.','Que lo atiendan gerencia o policía.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','hard',array['weapons','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lost_found','You find cash on the nightstand of a checked-out room. What do you do?','Encuentras dinero en el buró de un cuarto que ya salió. ¿Qué haces?','["Leave it", "Keep it as a tip", "Turn it in to lost and found with room and date", "Split it"]'::jsonb,'["Dejarlo", "Quedártelo como propina", "Entregarlo a objetos perdidos con cuarto y fecha", "Repartirlo"]'::jsonb,2,'Unless clearly marked as a tip, it''s lost property.','Si no dice propina, es objeto perdido.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','easy',array['lost_found','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tips','An envelope on the pillow says ''Housekeeping — thank you''. What is it?','Un sobre en la almohada dice ''Housekeeping — gracias''. ¿Qué es?','["Guest trash", "Something to return", "Lost property", "A tip for you — follow the hotel''s tip policy"]'::jsonb,'["Basura", "Algo para devolver", "Objeto perdido", "Una propina para ti; sigue la política del hotel"]'::jsonb,3,'Marked tips belong to housekeeping per policy.','Las propinas marcadas son de housekeeping.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['tips','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pests','Besides bed bugs, which pest sign should you report from a room?','Aparte de chinches, ¿qué plaga reportas de un cuarto?','["Hair", "Dust", "Cockroaches, mouse droppings, or ants", "Lint"]'::jsonb,'["Cabello", "Polvo", "Cucarachas, excremento de ratón u hormigas", "Pelusa"]'::jsonb,2,'Report any pest so pest control can act.','Reporta cualquier plaga.','https://www.epa.gov/bedbugs',array['hk_supervisor','houseman','room_attendant']::text[],'role','med',array['pests','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','glass','How do you pick up broken glass?','¿Cómo recoges vidrio roto?','["With your hands", "Vacuum big pieces", "Use a broom and dustpan, never bare hands; wrap it before trash", "With a towel and shake it"]'::jsonb,'["Con la mano", "Aspirar los pedazos grandes", "Con escoba y recogedor; nunca con la mano; envolverlo", "Con toalla y sacudirla"]'::jsonb,2,'Prevents cuts to you and trash handlers.','Evita cortadas.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','easy',array['glass','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','door','When you finish a room, what do you check before leaving?','Al terminar un cuarto, ¿qué revisas antes de salir?','["Door closes and locks behind you", "TV on", "Window open", "Lights on"]'::jsonb,'["Que la puerta cierre con seguro", "Tele prendida", "Ventana abierta", "Luces prendidas"]'::jsonb,0,'Secure the room.','Asegura el cuarto.','general hospitality best practice',array['hk_supervisor','houseman','room_attendant']::text[],'role','easy',array['door','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','You see a child alone in the pool area. What do you do?','Ves a un niño solo en la alberca. ¿Qué haces?','["Leave", "Jump in", "Stay nearby and alert the front desk so a parent is found", "Ignore"]'::jsonb,'["Irte", "Meterte", "Quedarte cerca y avisar a recepción para encontrar a sus papás", "Ignorar"]'::jsonb,2,'Unattended children near water are a drowning risk.','Riesgo de ahogamiento.','https://www.cdc.gov/drowning/prevention/index.html',array['hk_supervisor','houseman','room_attendant']::text[],'role','easy',array['pool','housekeeping','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','linen','Why deliver linen to floor closets before room attendants start?','¿Por qué surtir ropa en los pisos antes de que empiecen las recamareras?','["So they can start rooms without waiting", "For inspection only", "No reason", "It''s optional"]'::jsonb,'["Para que empiecen sin esperar", "Solo para inspección", "Por nada", "Es opcional"]'::jsonb,0,'Early stocking keeps the day on time.','Surtir temprano mantiene el ritmo.','general hospitality best practice',array['houseman']::text[],'role','med',array['linen','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trash','Trash chute or compactor: what''s the main rule?','Ducto de basura o compactador: ¿regla principal?','["Never reach or climb in; only trained staff operate the compactor", "Leave it running open", "Push trash with your foot", "Ride it"]'::jsonb,'["Nunca meter la mano ni subirte; solo personal capacitado", "Dejarlo abierto", "Empujar con el pie", "Subirte"]'::jsonb,0,'Compactors cause crush injuries.','Los compactadores aplastan.','https://www.osha.gov/control-hazardous-energy',array['houseman']::text[],'role','med',array['trash','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','carts','A linen cart wheel is broken. What do you do?','Una llanta del carro está rota. ¿Qué haces?','["Hide it", "Tag it and report it — don''t use it", "Carry it", "Keep using it"]'::jsonb,'["Esconderlo", "Etiquetarlo y reportarlo; no usarlo", "Cargarlo", "Seguir usándolo"]'::jsonb,1,'Broken carts cause strains.','Los carros rotos causan lesiones.','https://www.osha.gov/ergonomics',array['houseman']::text[],'role','easy',array['carts','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','public','The lobby restroom is out of soap. How fast should you fix it?','Se acabó el jabón en el baño del lobby. ¿Qué tan rápido lo arreglas?','["When asked twice", "Tomorrow", "End of shift", "Right away — it''s guest-facing and a hygiene need"]'::jsonb,'["Cuando pidan dos veces", "Mañana", "Al final del turno", "De inmediato; es área de huéspedes e higiene"]'::jsonb,3,'Handwashing needs soap.','Para lavarse se necesita jabón.','https://www.cdc.gov/clean-hands/about/index.html',array['houseman']::text[],'role','easy',array['public','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','glass','A guest broke a glass on the pool deck. What do you do?','Un huésped rompió un vaso en la alberca. ¿Qué haces?','["Sweep quickly", "Let guests stay", "Ignore", "Close the area, clean all pieces, and tell maintenance in case glass is in the water"]'::jsonb,'["Barrer rápido", "Dejar a los huéspedes", "Ignorar", "Cerrar el área, limpiar todo y avisar a mantenimiento por si cayó al agua"]'::jsonb,3,'Glass in pool water may require draining.','El vidrio en el agua puede requerir vaciarla.','general hospitality best practice',array['houseman']::text[],'role','med',array['glass','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','Why never put rubber-backed bath mats in a hot dryer?','¿Por qué no meter tapetes con hule a secadora caliente?','["They shrink", "Rubber can break down and is a fire risk", "They fade", "It''s fine"]'::jsonb,'["Se encogen", "El hule se degrada y puede incendiarse", "Se destiñen", "Está bien"]'::jsonb,1,'Follow care labels; use low heat or air dry.','Sigue la etiqueta.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','med',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','Why remove linen from the dryer promptly even after cool-down?','¿Por qué sacar la ropa pronto aun después de enfriar?','["Piled warm linen can still self-heat", "It shrinks", "No reason", "It gets cold"]'::jsonb,'["La ropa tibia amontonada aún puede calentarse sola", "Se encoge", "Por nada", "Se enfría"]'::jsonb,0,'Spontaneous heating is a known laundry fire cause.','Causa conocida de incendios.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','hard',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','What does the SDS tell you?','¿Qué te dice la SDS?','["Hazards, PPE, first aid and spill steps for a chemical", "The color", "Delivery date", "The price"]'::jsonb,'["Peligros, EPP, primeros auxilios y derrames", "Color", "Fecha de entrega", "Precio"]'::jsonb,0,'OSHA HazCom.','HazCom.','https://www.osha.gov/hazcom',array['laundry']::text[],'role','easy',array['chemicals','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','washer','The washer door won''t open after a cycle. What do you do?','La puerta de la lavadora no abre. ¿Qué haces?','["Pry it", "Kick it", "Wait for the lock to release; don''t force it; call maintenance if stuck", "Unplug and force"]'::jsonb,'["Forzarla", "Patearla", "Esperar a que se libere; no forzar; llamar a mantenimiento", "Desconectar y forzar"]'::jsonb,2,'Door interlocks prevent injury.','El seguro evita lesiones.','https://www.osha.gov/control-hazardous-energy',array['laundry']::text[],'role','med',array['washer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sorting','Why sort linen by type before washing?','¿Por qué separar ropa por tipo antes de lavar?','["Each type needs its own formula and temperature", "It doesn''t matter", "For counting only", "Faster drying only"]'::jsonb,'["Cada tipo necesita su fórmula y temperatura", "No importa", "Solo para contar", "Solo secado"]'::jsonb,0,'Proper formulas protect linen.','Las fórmulas cuidan la ropa.','https://www.ftc.gov/business-guidance/resources/clothes-captions-complying-care-labeling-rule',array['laundry']::text[],'role','easy',array['sorting','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stains','What usually removes blood stains best?','¿Qué quita mejor las manchas de sangre?','["Hot water", "Cold water first — hot water sets protein", "Dryer", "Bleach and ammonia"]'::jsonb,'["Agua caliente", "Agua fría primero; la caliente la fija", "Secadora", "Cloro con amoníaco"]'::jsonb,1,'Protein stains set with heat.','El calor fija la proteína.','https://www.cdc.gov/infection-control/hcp/environmental-control/laundry-bedding.html',array['laundry']::text[],'role','med',array['stains','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','How high should folding tables be?','¿Qué altura deben tener las mesas de doblado?','["Floor level", "About waist height to avoid bending", "Over your head", "Any"]'::jsonb,'["A nivel del piso", "A la cintura para no agacharte", "Arriba de la cabeza", "Cualquiera"]'::jsonb,1,'OSHA ergonomics.','Ergonomía OSHA.','https://www.osha.gov/ergonomics',array['laundry']::text[],'role','easy',array['ergonomics','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','count','Why count soiled linen going out (or in)?','¿Por qué contar la ropa sucia que sale o entra?','["Busywork", "For guests", "No reason", "Tracks loss and helps ordering"]'::jsonb,'["Papeleo", "Para huéspedes", "Por nada", "Controla pérdidas y ayuda a pedir"]'::jsonb,3,'Inventory control.','Control de inventario.','general hospitality best practice',array['laundry']::text[],'role','med',array['count','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lint','Lint piles on the laundry floor are a…','Pelusa en el piso de lavandería es…','["Good insulation", "Decoration", "Fire and slip hazard — sweep it", "Harmless"]'::jsonb,'["Buen aislante", "Adorno", "Riesgo de incendio y resbalón; barrer", "Inofensiva"]'::jsonb,2,'Lint is very flammable.','La pelusa es muy inflamable.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','easy',array['lint','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','A guest says their room wasn''t cleaned. What''s the best first response?','Un huésped dice que no le limpiaron el cuarto. ¿Mejor primera respuesta?','["Blame the shift", "Ask why they didn''t call earlier", "Apologize, thank them for telling you, and offer a fix and timing", "Say housekeeping is busy"]'::jsonb,'["Culpar al turno", "Preguntar por qué no llamó antes", "Disculparte, agradecer que te lo diga y ofrecer solución y hora", "Decir que limpieza está ocupada"]'::jsonb,2,'Service recovery: listen, apologize, solve, follow up.','Escuchar, disculparse, resolver, dar seguimiento.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['recovery','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','What''s the last step of good service recovery that''s often skipped?','¿Cuál es el último paso de la recuperación que suele olvidarse?','["Following up to make sure the fix worked", "Telling the GM only", "Writing a policy", "Charging a fee"]'::jsonb,'["Dar seguimiento para confirmar que se resolvió", "Solo avisar al gerente", "Escribir una política", "Cobrar"]'::jsonb,0,'Follow-up turns complaints into loyalty.','El seguimiento genera lealtad.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['recovery','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','A guest is yelling at the desk. What helps de-escalate?','Un huésped grita en recepción. ¿Qué ayuda a calmarlo?','["Yell back", "Stay calm, lower your voice, listen and repeat back their concern", "Walk away mid-sentence", "Laugh"]'::jsonb,'["Gritarle", "Mantener la calma, bajar la voz, escuchar y repetir su queja", "Irte a media frase", "Reírte"]'::jsonb,1,'Calm tone and active listening de-escalate.','Tono calmado y escucha activa.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['recovery','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','When should you offer compensation (points, discount) for a complaint?','¿Cuándo ofrecer compensación por una queja?','["After fixing the issue, within your authority, matched to the impact", "Never", "Only if they threaten a review", "Always, before listening"]'::jsonb,'["Después de resolver, dentro de tu autoridad y según el impacto", "Nunca", "Solo si amenazan con reseña", "Siempre, antes de escuchar"]'::jsonb,0,'Fix first; compensate proportionally.','Primero resolver; compensar según el caso.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','hard',array['recovery','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','A guest posts a bad review. Who should reply, and how?','Un huésped deja una mala reseña. ¿Quién responde y cómo?','["Nobody", "Anyone, defensively", "The GM or designee — thank, apologize, address the issue, invite them back", "Argue the facts publicly"]'::jsonb,'["Nadie", "Cualquiera, a la defensiva", "El gerente o designado: agradecer, disculparse, atender y invitar de nuevo", "Discutir en público"]'::jsonb,2,'Professional replies help future guests.','Responder profesional ayuda.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['recovery','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','recovery','Noise complaint from a guest at 11 p.m. First step?','Queja de ruido a las 11 p. m. ¿Primer paso?','["Call police first", "Thank them, call the noisy room politely, and follow up with the guest", "Ignore it", "Move the complainer immediately"]'::jsonb,'["Llamar a la policía primero", "Agradecer, llamar con cortesía al cuarto ruidoso y dar seguimiento", "Ignorarla", "Cambiar al que se queja de inmediato"]'::jsonb,1,'Escalate only if needed.','Escalar solo si hace falta.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['recovery','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','upsell','What''s a good way to offer a room upgrade?','¿Cuál es una buena forma de ofrecer mejora de cuarto?','["Push every guest hard", "Never offer", "Only mention price", "Describe a benefit that fits their trip and quote the difference"]'::jsonb,'["Presionar a todos", "Nunca ofrecer", "Solo decir el precio", "Describir un beneficio que le sirva y dar la diferencia"]'::jsonb,3,'Benefit-based offers feel helpful, not pushy.','Ofrecer beneficios ayuda.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['upsell','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','upsell','A family of 5 checks into a standard room. What could you offer?','Una familia de 5 llega a un cuarto estándar. ¿Qué ofrecerías?','["A parking spot", "A smaller room", "Nothing", "A suite or larger room for space — if available"]'::jsonb,'["Estacionamiento", "Un cuarto más chico", "Nada", "Una suite o cuarto más grande, si hay"]'::jsonb,3,'Match offers to needs.','Ofrecer según la necesidad.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['upsell','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','upsell','When is the best moment to offer an upgrade at check-in?','¿Cuándo es mejor ofrecer mejora al registrarse?','["After greeting and confirming the reservation, before keys are made", "After they leave", "Never", "While the line is out the door"]'::jsonb,'["Después de saludar y confirmar, antes de hacer llaves", "Cuando se van", "Nunca", "Con la fila larga"]'::jsonb,0,'Natural moment in the flow.','Momento natural.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['upsell','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','What details must you confirm when taking a reservation?','¿Qué datos confirmas al tomar una reservación?','["Only card", "Only name", "Only dates", "Name, dates, room type, rate, guests, and how to contact them"]'::jsonb,'["Solo tarjeta", "Solo nombre", "Solo fechas", "Nombre, fechas, tipo de cuarto, tarifa, personas y contacto"]'::jsonb,3,'Read-backs prevent errors.','Repetir evita errores.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['reservations','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','Why read back the dates and rate to the caller?','¿Por qué repetir fechas y tarifa al cliente?','["Required by phone company", "No reason", "Catches mistakes before the stay", "It''s polite filler"]'::jsonb,'["Lo pide la compañía", "Por nada", "Detecta errores antes de la estancia", "Solo cortesía"]'::jsonb,2,'Confirmation prevents disputes.','Evita disputas.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['reservations','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','A guest wants to cancel. What do you check first?','Un huésped quiere cancelar. ¿Qué revisas primero?','["Nothing — just cancel", "The rate''s cancellation policy and deadline", "Their age", "Their car"]'::jsonb,'["Nada", "La política de cancelación de su tarifa y fecha límite", "Su edad", "Su carro"]'::jsonb,1,'Rates differ — prepaid vs flexible.','Las tarifas cambian.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['reservations','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','What''s a ''no-show''?','¿Qué es un ''no-show''?','["A guest who leaves early", "A cancelled room", "A guest with a guaranteed reservation who never arrives or cancels", "A walk-in"]'::jsonb,'["Huésped que sale antes", "Cuarto cancelado", "Huésped con reservación garantizada que no llega ni cancela", "Sin reservación"]'::jsonb,2,'No-show policies apply the guarantee.','Se aplica la garantía.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','hard',array['reservations','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reservations','The hotel is oversold and a guest must be ''walked''. What''s expected?','El hotel está sobrevendido y hay que reubicar a un huésped. ¿Qué se espera?','["Apologize, book them at a nearby comparable hotel, and arrange transport per policy", "Put them in the lobby", "Tell them to find a room", "Charge them"]'::jsonb,'["Disculparse, reservarle hotel cercano similar y transporte según política", "Dejarlo en el lobby", "Que busque cuarto", "Cobrarle"]'::jsonb,0,'Walk procedures protect the guest experience.','El procedimiento protege al huésped.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['reservations','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','A guest under the minimum check-in age wants a room. What do you do?','Un menor de la edad mínima quiere cuarto. ¿Qué haces?','["Politely decline per policy — the registered guest must meet the age", "Give it anyway", "Charge extra", "Ask a stranger to sign"]'::jsonb,'["Negarlo con cortesía según la política", "Darlo igual", "Cobrar extra", "Que firme un desconocido"]'::jsonb,0,'Age policies are part of the registration contract.','La edad es parte del registro.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['policy','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','Why match photo ID to the name on the reservation and card?','¿Por qué comparar identificación con reservación y tarjeta?','["For points only", "Only for marketing", "It''s optional", "Prevents fraud and protects the real guest"]'::jsonb,'["Solo puntos", "Solo mercadeo", "Es opcional", "Evita fraude y protege al huésped real"]'::jsonb,3,'ID check is basic fraud control.','Control básico de fraude.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['policy','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','What is an ''incidental hold''?','¿Qué es una ''retención para gastos''?','["A tax", "A cash tip", "A temporary authorization on the card to cover possible charges", "A fee kept forever"]'::jsonb,'["Impuesto", "Propina", "Una autorización temporal en la tarjeta para posibles cargos", "Un cargo permanente"]'::jsonb,2,'Authorizations are released after checkout per the bank.','Se libera tras la salida según el banco.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['policy','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','policy','A guest''s debit card hold still shows days after checkout. What do you explain?','Al huésped le sigue la retención en su débito días después. ¿Qué le explicas?','["We kept the money", "It''s permanent", "Call the police", "We released it; the bank controls how fast it drops off"]'::jsonb,'["Nos quedamos el dinero", "Es permanente", "Que llame a la policía", "Ya la liberamos; el banco decide cuánto tarda"]'::jsonb,3,'Banks control authorization release timing.','El banco controla los tiempos.','https://www.consumerfinance.gov/ask-cfpb/what-is-a-chargeback-en-2031/',array['front_desk','gm','night_audit']::text[],'role','hard',array['policy','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','law','Minnesota law lets a hotel limit its liability for guest valuables if it…','La ley de MN limita la responsabilidad del hotel por valores si…','["Has cameras", "Offers a safe and posts the required notice", "Never — always liable", "Says so verbally"]'::jsonb,'["Tiene cámaras", "Ofrece caja fuerte y pone el aviso requerido", "Nunca", "Lo dice de palabra"]'::jsonb,1,'MN Stat. 327.70 (innkeeper liability with safe and notice).','Estatuto 327.70 de MN.','https://www.revisor.mn.gov/statutes/cite/327.70',array['front_desk','gm','night_audit']::text[],'role','hard',array['law','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','law','Under Minnesota law, can a hotel remove a guest who''s disorderly or won''t pay?','Según la ley de MN, ¿puede el hotel sacar a un huésped que causa desorden o no paga?','["Yes, the innkeeper may eject them, using police if needed", "No, never", "Only with a court order", "Only after 30 days"]'::jsonb,'["Sí, el hotelero puede sacarlo, con policía si hace falta", "Nunca", "Solo con orden judicial", "Solo tras 30 días"]'::jsonb,0,'MN Stat. 327.73.','Estatuto 327.73.','https://www.revisor.mn.gov/statutes/cite/327.73',array['front_desk','gm','night_audit']::text[],'role','hard',array['law','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ada','A guest asks for an accessible room you have open. Can you give it to a non-disabled guest first?','Un huésped pide un cuarto accesible disponible. ¿Lo das primero a alguien sin discapacidad?','["Yes, always", "Yes, first come", "Accessible rooms should be held for guests who need them until others are booked", "Only VIPs"]'::jsonb,'["Siempre", "Sí, el primero", "Los accesibles se reservan para quienes los necesitan hasta que se agoten los demás", "Solo VIP"]'::jsonb,2,'DOJ ADA hotel reservations rule.','Regla ADA de reservaciones del DOJ.','https://www.ada.gov/topics/hotels/',array['front_desk','gm','night_audit']::text[],'role','med',array['ada','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ada','A deaf guest asks how they''ll know about a fire alarm. What do you offer?','Un huésped sordo pregunta cómo sabrá de una alarma. ¿Qué le ofreces?','["Nothing", "A whistle", "Tell them to stay awake", "A hearing-accessible kit or room with visual alarms"]'::jsonb,'["Nada", "Un silbato", "Que no duerma", "Un kit o cuarto auditivo con alarma visual"]'::jsonb,3,'ADA requires communication features.','La ADA exige estos recursos.','https://www.ada.gov/topics/hotels/',array['front_desk','gm','night_audit']::text[],'role','easy',array['ada','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','When you start a shift with a bank, what do you do first?','Al iniciar turno con fondo, ¿qué haces primero?','["Trust it", "Count at the end only", "Start selling", "Count it and sign that it matches"]'::jsonb,'["Confiar", "Contar solo al final", "Empezar a cobrar", "Contarlo y firmar que cuadra"]'::jsonb,3,'Verifies accountability.','Garantiza responsabilidad.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['cash','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','How do you give change to avoid mistakes?','¿Cómo das cambio sin errores?','["Round up", "Guess", "Leave the guest''s bill out until change is counted back", "Put the bill away first"]'::jsonb,'["Redondear", "Adivinar", "Dejar el billete fuera hasta contar el cambio", "Guardar el billete primero"]'::jsonb,2,'Prevents ''I gave you a $50'' disputes.','Evita disputas.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['cash','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','How can you check a $100 bill is real?','¿Cómo revisas que un billete de $100 sea real?','["Fold it", "Look at the serial only", "Tilt it for the color-shifting 100 and 3-D ribbon; check the watermark", "Smell it"]'::jsonb,'["Doblarlo", "Solo serie", "Inclinarlo: 100 que cambia de color, cinta 3D y marca de agua", "Olerlo"]'::jsonb,2,'US Secret Service/uscurrency.gov features.','Elementos oficiales.','https://www.uscurrency.gov/denominations/100',array['front_desk','gm','night_audit']::text[],'role','med',array['cash','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','You suspect a counterfeit bill. What should you do?','Sospechas un billete falso. ¿Qué haces?','["Give it back and say nothing", "Don''t return it if safe to keep; note the passer''s description and call police", "Tear it", "Spend it"]'::jsonb,'["Devolverlo", "Si es seguro, no devolverlo; anotar la descripción y llamar a la policía", "Romperlo", "Gastarlo"]'::jsonb,1,'Secret Service guidance.','Guía del Servicio Secreto.','https://www.secretservice.gov/investigations/counterfeit',array['front_desk','gm','night_audit']::text[],'role','hard',array['cash','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cash','Can you leave your cash drawer open and walk away?','¿Puedes dejar la caja abierta e irte?','["Yes, briefly", "If a guest watches", "Yes, at night", "No — lock it every time you step away"]'::jsonb,'["Sí, un momento", "Si un huésped vigila", "Sí, de noche", "No; ciérrala siempre"]'::jsonb,3,'Drawer control.','Control de caja.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['cash','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','payments','A caller asks you to read back the full card number on file. What do you do?','Alguien pide que le leas el número completo de la tarjeta. ¿Qué haces?','["Read it slowly", "Email it", "Text it", "Never — confirm only the last 4 digits"]'::jsonb,'["Leerlo despacio", "Enviarlo por correo", "Mandarlo por mensaje", "Nunca; solo confirmar los últimos 4"]'::jsonb,3,'PCI DSS protects cardholder data.','PCI DSS protege los datos.','https://www.pcisecuritystandards.org/standards/',array['front_desk','gm','night_audit']::text[],'role','med',array['payments','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','payments','Can you write a guest''s card number on a sticky note?','¿Puedes anotar el número de tarjeta en un papelito?','["Yes, then shred", "Yes, if hidden", "Only at night", "No — never store card data outside the secure system"]'::jsonb,'["Sí y luego triturar", "Sí si está escondido", "Solo de noche", "No; nunca guardes datos fuera del sistema seguro"]'::jsonb,3,'PCI DSS.','PCI DSS.','https://www.pcisecuritystandards.org/standards/',array['front_desk','gm','night_audit']::text[],'role','med',array['payments','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','payments','An email from ''corporate'' asks you to wire money urgently and keep it secret. What is it likely?','Un correo de ''corporativo'' pide transferir dinero urgente y en secreto. ¿Qué es?','["A phishing/scam — verify by phone with a known number and tell your GM", "A normal request", "A bonus", "A test you must pass by paying"]'::jsonb,'["Fraude; verifica por teléfono con número conocido y avisa al gerente", "Normal", "Un bono", "Prueba que pasas pagando"]'::jsonb,0,'FTC: urgency + secrecy = scam.','FTC: urgencia y secreto = fraude.','https://consumer.ftc.gov/articles/how-recognize-and-avoid-phishing-scams',array['front_desk','gm','night_audit']::text[],'role','hard',array['payments','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','scam','A caller says they''re ''from the front desk'' and asks a guest for their card. What should guests know?','Alguien llama al huésped diciendo que es ''de recepción'' y pide su tarjeta. ¿Qué deben saber?','["Give it", "Read the CVV", "It''s normal", "The desk won''t call asking for card numbers — come to the desk instead"]'::jsonb,'["Darla", "Dar el CVV", "Es normal", "Recepción no llama pidiendo tarjetas; que bajen a recepción"]'::jsonb,3,'Common hotel phone scam (FTC).','Fraude común.','https://consumer.ftc.gov/articles/how-recognize-and-avoid-phishing-scams',array['front_desk','gm','night_audit']::text[],'role','med',array['scam','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Someone at the desk asks for a key to room 214 saying it''s their wife''s room. What do you do?','Alguien pide llave del 214 diciendo que es de su esposa. ¿Qué haces?','["Give a temporary key", "Give it", "Ask the room color", "Only give keys to registered guests with ID — offer to call the room"]'::jsonb,'["Llave temporal", "Dársela", "Preguntar el color", "Solo a huéspedes registrados con ID; ofrecer llamar al cuarto"]'::jsonb,3,'Key control protects guests.','Control de llaves.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['security','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','When saying a room number at check-in, what''s best?','Al dar el número de cuarto, ¿qué es mejor?','["Shout it", "Write it on the key packet instead of saying it aloud", "Announce it", "Post it"]'::jsonb,'["Gritarlo", "Escribirlo en el sobre en vez de decirlo", "Anunciarlo", "Publicarlo"]'::jsonb,1,'Others may overhear.','Otros escuchan.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['security','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','A guest reports their wallet stolen from the room. What do you do?','Un huésped reporta robo de cartera del cuarto. ¿Qué haces?','["Say it''s not our problem", "Search their room alone", "Take it seriously, notify the manager, offer to call police, and document it", "Accuse housekeeping"]'::jsonb,'["No es problema nuestro", "Revisar solo", "Tomarlo en serio, avisar al gerente, ofrecer llamar a policía y documentar", "Acusar a limpieza"]'::jsonb,2,'Document and escalate.','Documentar y escalar.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['security','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Police arrive asking for a guest''s room number without a warrant. What''s the standard practice?','La policía pide un número de cuarto sin orden. ¿Práctica estándar?','["Involve the manager; follow company policy on law-enforcement requests (registry privacy)", "Call the guest to warn", "Give everything instantly", "Refuse to talk"]'::jsonb,'["Llamar al gerente y seguir la política (privacidad del registro)", "Avisar al huésped", "Dar todo", "Negarse a hablar"]'::jsonb,0,'Supreme Court (City of LA v. Patel) recognized hotel registry privacy.','La Corte Suprema reconoció la privacidad del registro.','https://www.oyez.org/cases/2014/13-1175',array['front_desk','gm','night_audit']::text[],'role','hard',array['security','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','phone','How should you answer the hotel phone?','¿Cómo contestas el teléfono del hotel?','["Silence", "''Yeah?''", "Greeting, hotel name, your name, ''How may I help you?''", "Hotel name only"]'::jsonb,'["Silencio", "''¿Sí?''", "Saludo, nombre del hotel, tu nombre, ''¿En qué le ayudo?''", "Solo hotel"]'::jsonb,2,'A standard greeting sets the tone.','Saludo estándar.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['phone','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','phone','You must put a caller on hold. What''s polite?','Debes poner en espera. ¿Qué es cortés?','["Hang up", "Ask permission, wait for the answer, and check back within a minute", "Just press hold", "Leave them 10 minutes"]'::jsonb,'["Colgar", "Pedir permiso, esperar y volver en un minuto", "Solo poner espera", "Dejarlo 10 minutos"]'::jsonb,1,'Respect callers'' time.','Respeta su tiempo.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['phone','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','checkin','A guest arrives at 10 a.m. but check-in is 3 p.m. What can you offer?','Llega a las 10 a. m. y la entrada es a las 3. ¿Qué ofreces?','["Check availability for early check-in or store bags and take their number", "Tell them to come back", "Send them to another hotel", "Charge double"]'::jsonb,'["Ver si hay entrada temprana o guardar maletas y tomar su número", "Que vuelva", "Mandarlo a otro hotel", "Cobrar doble"]'::jsonb,0,'Flexibility builds goodwill.','La flexibilidad ayuda.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['checkin','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','checkin','Why use the guest''s name during check-in?','¿Por qué usar el nombre del huésped al registrarlo?','["No reason", "It personalizes service and shows attention", "To slow things down", "It''s required by law"]'::jsonb,'["Por nada", "Personaliza y muestra atención", "Para hacerlo lento", "Ley"]'::jsonb,1,'Personal touch.','Toque personal.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['checkin','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','checkout','A guest disputes a charge at checkout. What first?','Un huésped disputa un cargo. ¿Primero?','["Call security", "Remove all charges", "Listen, review the folio together, and fix errors or explain clearly", "Refuse"]'::jsonb,'["Llamar a seguridad", "Quitar todo", "Escuchar, revisar el folio juntos y corregir o explicar", "Negarse"]'::jsonb,2,'Clear folio review resolves most disputes.','Revisar resuelve casi todo.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['checkout','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','checkout','At checkout, what simple question can catch problems?','Al salir, ¿qué pregunta sencilla detecta problemas?','["''Pay now''", "''How was your stay?'' — and listen", "''Anything else to buy?''", "None"]'::jsonb,'["''Pague ya''", "''¿Cómo estuvo su estancia?'' y escuchar", "''¿Algo más?''", "Ninguna"]'::jsonb,1,'Last chance for recovery.','Última oportunidad.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['checkout','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency','A guest calls the desk with chest pain. What do you do?','Un huésped llama con dolor de pecho. ¿Qué haces?','["Tell them to rest", "Send them a taxi", "Call 911, send someone with the AED, and meet EMS at the door", "Call back later"]'::jsonb,'["Que descanse", "Mandar taxi", "Llamar al 911, mandar a alguien con el DEA y recibir a la ambulancia", "Llamar después"]'::jsonb,2,'Fast EMS and AED save lives.','El 911 y el DEA salvan vidas.','https://www.redcross.org/take-a-class/aed/using-an-aed',array['front_desk','gm','night_audit']::text[],'role','med',array['emergency','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency','During a fire alarm, what''s the desk''s key job?','Durante una alarma de incendio, ¿qué hace recepción?','["Hide", "Silence the alarm", "Keep checking in", "Follow the plan: call 911/confirm, grab the in-house guest list, direct people out, meet firefighters"]'::jsonb,'["Esconderse", "Apagar la alarma", "Seguir registrando", "Seguir el plan: 911, lista de huéspedes, guiar la salida, recibir a bomberos"]'::jsonb,3,'Front desk supports evacuation.','Recepción apoya la evacuación.','https://www.osha.gov/etools/evacuation-plans-procedures',array['front_desk','gm','night_audit']::text[],'role','med',array['emergency','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency','A guest''s child is missing in the hotel. What do you do?','Se perdió el niño de un huésped. ¿Qué haces?','["Wait an hour", "Announce room numbers", "Get a description, alert all staff to watch exits, search, and call 911 quickly", "Tell them to look"]'::jsonb,'["Esperar una hora", "Anunciar cuartos", "Pedir descripción, alertar al personal y salidas, buscar y llamar al 911 pronto", "Que busquen ellos"]'::jsonb,2,'Code Adam-style response.','Respuesta tipo Código Adam.','https://www.missingkids.org/gethelpnow/isyourchildmissing',array['front_desk','gm','night_audit']::text[],'role','med',array['emergency','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','handoff','At shift change, what should be in the pass-on log?','En el cambio de turno, ¿qué va en la bitácora?','["Gossip", "Your lunch", "Nothing", "Open issues, guest requests, VIPs, and follow-ups"]'::jsonb,'["Chismes", "Tu comida", "Nada", "Pendientes, peticiones, VIP y seguimientos"]'::jsonb,3,'A good log prevents dropped requests.','La bitácora evita olvidos.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['handoff','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','loyalty','Why ask every guest if they''re a loyalty member?','¿Por qué preguntar a cada huésped si es miembro?','["For taxes", "Only for VIPs", "They earn points and benefits, and the hotel gains repeat guests", "It''s not useful"]'::jsonb,'["Impuestos", "Solo VIP", "Ganan puntos y beneficios y el hotel gana lealtad", "No sirve"]'::jsonb,2,'Enrollment drives repeat business.','Genera regreso.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['loyalty','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tone','Which phrase is better at the desk?','¿Qué frase es mejor en recepción?','["''Policy says no''", "''Not my problem''", "''Let me see what I can do''", "''That''s not possible''"]'::jsonb,'["''La política dice que no''", "''No es mi problema''", "''Déjeme ver qué puedo hacer''", "''No se puede''"]'::jsonb,2,'Positive language keeps guests open.','Lenguaje positivo.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','easy',array['tone','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','language','A guest speaks only Spanish and you don''t. What helps?','Un huésped solo habla español y tú no. ¿Qué ayuda?','["Speak louder in English", "Ignore", "Send them away", "Ask a Spanish-speaking coworker or use a translation app politely"]'::jsonb,'["Hablar más fuerte en inglés", "Ignorar", "Mandarlo", "Pedir a un compañero que hable español o usar traductor con cortesía"]'::jsonb,3,'Find a way to communicate.','Busca comunicarte.','general hospitality best practice',array['front_desk','gm','night_audit']::text[],'role','med',array['language','front_desk','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What''s the night audit''s main job?','¿Cuál es el trabajo principal de la auditoría nocturna?','["Clean the lobby only", "Balance the day''s charges and payments and close the business day", "Take reservations only", "Sleep"]'::jsonb,'["Solo limpiar", "Cuadrar cargos y pagos del día y cerrar el día", "Solo reservar", "Dormir"]'::jsonb,1,'Night audit reconciles and rolls the date.','Concilia y cambia de día.','general hospitality best practice',array['gm','night_audit']::text[],'role','easy',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What is ADR?','¿Qué es el ADR?','["Rooms sold ÷ rooms available", "Guests per room", "Average Daily Rate: room revenue ÷ rooms sold", "Total revenue"]'::jsonb,'["Vendidos ÷ disponibles", "Huéspedes por cuarto", "Tarifa promedio: ingreso por cuartos ÷ cuartos vendidos", "Ingreso total"]'::jsonb,2,'Standard industry metric (STR).','Métrica estándar (STR).','https://str.com/data-insights/resources/glossary',array['gm','night_audit']::text[],'role','med',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What is occupancy?','¿Qué es la ocupación?','["ADR × rooms", "Rooms sold ÷ rooms available", "Arrivals today", "Revenue ÷ guests"]'::jsonb,'["ADR × cuartos", "Cuartos vendidos ÷ disponibles", "Llegadas de hoy", "Ingreso ÷ huéspedes"]'::jsonb,1,'STR glossary.','Glosario STR.','https://str.com/data-insights/resources/glossary',array['gm','night_audit']::text[],'role','med',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What is RevPAR?','¿Qué es el RevPAR?','["Rooms sold", "Revenue per guest", "Total profit", "Room revenue ÷ rooms available (or ADR × occupancy)"]'::jsonb,'["Vendidos", "Ingreso por huésped", "Utilidad", "Ingreso por cuartos ÷ disponibles (o ADR × ocupación)"]'::jsonb,3,'STR glossary.','Glosario STR.','https://str.com/data-insights/resources/glossary',array['gm','night_audit']::text[],'role','hard',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','80 rooms sold of 100, ADR $120. What''s RevPAR?','80 de 100 vendidos, ADR $120. ¿RevPAR?','["$96", "$120", "$150", "$80"]'::jsonb,'["$96", "$120", "$150", "$80"]'::jsonb,0,'0.80 × $120 = $96.','0.80 × $120 = $96.','https://str.com/data-insights/resources/glossary',array['gm','night_audit']::text[],'role','hard',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','Your cash drawer is $20 short at audit. What do you do?','Tu caja tiene $20 de menos. ¿Qué haces?','["Add your own money silently", "Change the report", "Recount, check transactions, and report it honestly to the manager", "Ignore"]'::jsonb,'["Poner tu dinero", "Cambiar el reporte", "Recontar, revisar movimientos y reportarlo al gerente", "Ignorar"]'::jsonb,2,'Honest variance reporting.','Reportar con honestidad.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What''s a ''room and rate'' discrepancy check?','¿Qué es revisar ''cuarto y tarifa''?','["Comparing every in-house room''s rate to its reservation/rate code", "Calling guests", "Counting towels", "Checking lights"]'::jsonb,'["Comparar la tarifa de cada cuarto ocupado con su reservación", "Llamar huéspedes", "Contar toallas", "Revisar luces"]'::jsonb,0,'Catches wrong rates before posting.','Detecta tarifas mal.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','Why compare housekeeping room status with the front desk system?','¿Por qué comparar el estado de limpieza con el sistema?','["To catch skips, sleepers and wrong statuses", "No reason", "To count beds", "For fun"]'::jsonb,'["Para detectar ''skips'', ''sleepers'' y estados mal", "Por nada", "Contar camas", "Diversión"]'::jsonb,0,'Room status reconciliation.','Conciliación de estado.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What is a ''skip'' at the front desk?','¿Qué es un ''skip'' en recepción?','["A guest who left without paying or checking out", "A late arrival", "A room upgrade", "A no-show"]'::jsonb,'["Huésped que se fue sin pagar ni salir", "Llegada tarde", "Mejora", "No-show"]'::jsonb,0,'Skips must be reported and pursued.','Se reportan.','general hospitality best practice',array['gm','night_audit']::text[],'role','hard',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What is a ''sleeper''?','¿Qué es un ''sleeper''?','["A no-show", "A room shown occupied in the system but actually vacant", "A guest asleep", "A cot"]'::jsonb,'["No-show", "Cuarto ocupado en sistema pero vacío", "Huésped dormido", "Catre"]'::jsonb,1,'Status errors cost revenue.','Errores cuestan dinero.','general hospitality best practice',array['gm','night_audit']::text[],'role','hard',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','A walk-in arrives at 2 a.m. without ID. What do you do?','Llega alguien a las 2 a. m. sin identificación. ¿Qué haces?','["Let them sleep in the lobby", "Ask for cash double", "Rent it anyway", "Follow policy — ID is required; politely decline if none"]'::jsonb,'["Que duerma en el lobby", "Cobrar doble", "Rentar igual", "Seguir la política: se requiere ID; negar con cortesía"]'::jsonb,3,'ID policy applies 24/7.','Aplica siempre.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','Overnight, how do you keep the lobby secure?','De noche, ¿cómo mantienes seguro el lobby?','["Follow door/lock procedures, watch cameras, and walk rounds per policy", "Leave the desk unattended", "Sleep", "Prop doors open"]'::jsonb,'["Seguir cierres, ver cámaras y hacer rondas", "Dejar la recepción sola", "Dormir", "Dejar puertas abiertas"]'::jsonb,0,'Night security routine.','Rutina de seguridad.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','A non-guest is sleeping in the lobby at 3 a.m. What do you do?','Alguien que no es huésped duerme en el lobby a las 3 a. m. ¿Qué haces?','["Physically remove them", "Yell", "Approach calmly, ask if they need help, and follow policy (call police if unsafe)", "Ignore forever"]'::jsonb,'["Sacarlo a la fuerza", "Gritar", "Acercarte con calma, preguntar si necesita ayuda y seguir la política", "Ignorar"]'::jsonb,2,'Safety and dignity.','Seguridad y dignidad.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','You''re alone overnight and feel unsafe. What should you do?','Estás sola de noche y te sientes insegura. ¿Qué haces?','["Handle it alone", "Call the manager on duty or 911 — don''t confront", "Ignore", "Leave the building"]'::jsonb,'["Resolverlo sola", "Llamar al gerente de turno o al 911; no enfrentar", "Ignorar", "Salir"]'::jsonb,1,'Your safety first.','Tu seguridad primero.','general hospitality best practice',array['gm','night_audit']::text[],'role','easy',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','Why print or save an in-house guest list overnight?','¿Por qué imprimir la lista de huéspedes de noche?','["If the system or power fails during an emergency, you know who''s in the building", "For marketing", "No reason", "To call guests"]'::jsonb,'["Si falla el sistema en emergencia, sabes quién está", "Mercadeo", "Por nada", "Llamar"]'::jsonb,0,'Emergency readiness.','Preparación.','https://www.osha.gov/etools/evacuation-plans-procedures',array['gm','night_audit']::text[],'role','med',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','Why back up reports before rolling the date?','¿Por qué respaldar reportes antes de cambiar la fecha?','["It''s optional", "Once rolled, the prior day can''t easily be changed — you need records", "For decoration", "To print coupons"]'::jsonb,'["Opcional", "Una vez cerrado, no se cambia fácil; necesitas registro", "Adorno", "Cupones"]'::jsonb,1,'Audit trail.','Rastro de auditoría.','general hospitality best practice',array['gm','night_audit']::text[],'role','hard',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','night','A guest calls at 4 a.m. locked out of their room in a towel. What do you do?','Un huésped llama a las 4 a. m. encerrado fuera en toalla. ¿Qué haces?','["Verify identity discreetly (name, details matching registration), then help them in", "Laugh", "Give a key without checking", "Refuse"]'::jsonb,'["Verificar identidad con discreción y luego ayudarlo", "Reírte", "Dar llave sin verificar", "Negar"]'::jsonb,0,'Balance kindness and security.','Amabilidad y seguridad.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['night','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ice_machine','Why clean and sanitize the ice machine on a schedule?','¿Por qué limpiar y desinfectar la máquina de hielo con calendario?','["Ice is food — slime and mold can grow inside", "To make more noise", "No reason", "For looks"]'::jsonb,'["El hielo es alimento; dentro crece moho y lama", "Más ruido", "Por nada", "Estética"]'::jsonb,0,'FDA Food Code treats ice as food; follow the maker''s cleaning schedule.','El Código FDA considera el hielo alimento.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['maintenance']::text[],'role','med',array['ice_machine','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','doors','A guest room door doesn''t close and latch by itself. Why fix it fast?','La puerta del cuarto no cierra sola. ¿Por qué arreglarla rápido?','["Security, and corridor doors must self-close for fire safety", "Guests like it open", "No reason", "It squeaks"]'::jsonb,'["Seguridad, y deben cerrar solas por incendios", "Les gusta abierta", "Por nada", "Rechina"]'::jsonb,0,'Self-closing doors limit smoke spread.','Las puertas que cierran solas frenan el humo.','https://www.osha.gov/exit-routes',array['maintenance']::text[],'role','easy',array['doors','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','exit_signs','An exit sign is dark. What do you do?','Un letrero de salida está apagado. ¿Qué haces?','["Remove it", "Wait for inspection", "Cover it", "Repair it promptly — exit signs must stay lit"]'::jsonb,'["Quitarlo", "Esperar inspección", "Taparlo", "Repararlo pronto; deben estar encendidos"]'::jsonb,3,'OSHA 1910.37: exits must be clearly marked and illuminated.','OSHA 1910.37.','https://www.osha.gov/exit-routes',array['maintenance']::text[],'role','med',array['exit_signs','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency_lights','How often should emergency lights be function-tested?','¿Cada cuánto se prueban las luces de emergencia?','["Every 10 years", "Never", "Monthly 30-second test and a yearly 90-minute test", "Only after a blackout"]'::jsonb,'["Cada 10 años", "Nunca", "Prueba mensual de 30 segundos y anual de 90 minutos", "Solo tras un apagón"]'::jsonb,2,'NFPA 101 emergency lighting tests.','Pruebas de NFPA 101.','https://www.nfpa.org/codes-and-standards/nfpa-101-standard-development/101',array['maintenance']::text[],'role','med',array['emergency_lights','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','gas','You smell natural gas in the boiler room. What do you do?','Hueles gas en el cuarto de calderas. ¿Qué haces?','["Turn on fans", "Keep working", "Light a match to find it", "Don''t flip switches or use phones there; leave, evacuate if needed, call 911 and the gas utility from outside"]'::jsonb,'["Prender ventiladores", "Seguir", "Prender un cerillo", "No prender interruptores ni usar teléfono ahí; salir, evacuar si hace falta y llamar al 911 y a la compañía de gas desde afuera"]'::jsonb,3,'Utility gas-leak guidance: any spark can ignite gas.','Cualquier chispa puede encenderlo.','https://www.centerpointenergy.com/en-us/safety/natural-gas-safety',array['maintenance']::text[],'role','hard',array['gas','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','waffle_batter','Waffle batter made with milk and eggs sits out on the buffet. What keeps it safe?','La mezcla de waffles con leche y huevo está en el buffet. ¿Qué la mantiene segura?','["Add water", "Cover with a towel", "Keep it cold (41°F or below) or follow the time limit, and refill in small batches", "Leave it out all morning"]'::jsonb,'["Echarle agua", "Taparla con toalla", "Mantenerla fría (41°F o menos) o seguir el límite de tiempo, y rellenar en porciones", "Dejarla toda la mañana"]'::jsonb,2,'Food Code: perishable mixes need temperature or time control.','Código FDA: control de tiempo o temperatura.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['waffle_batter','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','time_control','Under Food Code ''time as a control'', how long can a cold item sit out without temperature control?','Con ''tiempo como control'', ¿cuánto puede estar un alimento frío sin control de temperatura?','["Forever", "Up to 6 hours if it started at 41°F or below and stays under 70°F", "15 minutes", "24 hours"]'::jsonb,'["Para siempre", "Hasta 6 horas si empezó a 41°F o menos y no pasa de 70°F", "15 minutos", "24 horas"]'::jsonb,1,'Food Code 3-501.19: 4 hours (hot or cold) or 6 hours cold under 70°F, with written procedures.','Código 3-501.19.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','hard',array['time_control','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','utensils','How should serving utensils sit in buffet food?','¿Cómo se dejan los utensilios en el buffet?','["Handles buried in food", "Handles up, out of the food", "On the floor", "In the guest''s plate"]'::jsonb,'["Mango dentro", "Mango arriba, fuera de la comida", "En el piso", "En el plato"]'::jsonb,1,'Food Code: handles above the food.','Mangos fuera de la comida.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['utensils','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','reuse','A guest brings a used plate back for seconds. What''s best?','Un huésped regresa con el plato usado para servirse otra vez. ¿Qué es lo mejor?','["Politely offer a clean plate", "Refuse food", "Wipe it with a napkin", "Let them use it"]'::jsonb,'["Ofrecerle con cortesía un plato limpio", "Negarle comida", "Limpiarlo con servilleta", "Dejarlo"]'::jsonb,0,'Food Code: guests use clean tableware for refills at buffets.','Código FDA: plato limpio para repetir.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['reuse','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','milk','Where should the milk dispenser or jugs be kept?','¿Dónde se mantiene la leche?','["On the counter all morning", "In a warm cabinet", "Next to the coffee machine", "In a cooler or on ice at 41°F or below"]'::jsonb,'["En el mostrador toda la mañana", "En un gabinete tibio", "Junto a la cafetera", "En refrigerador o hielo a 41°F o menos"]'::jsonb,3,'Cold holding rule.','Regla de frío.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['milk','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cereal','Why use dispensers or scoops for cereal instead of open bowls?','¿Por qué usar dispensadores para cereal en vez de tazones abiertos?','["No reason", "Keeps hands out of shared food", "Looks fancy", "Cereal lasts forever"]'::jsonb,'["Por nada", "Evita que metan la mano", "Se ve elegante", "El cereal dura siempre"]'::jsonb,1,'Protect self-service food.','Protege la comida.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['cereal','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','audit','What should the night auditor check before closing the day?','¿Qué revisa el auditor nocturno antes de cerrar el día?','["Only the coffee pot", "Nothing — run it right away", "Just the TV in the lobby", "Arrivals are checked in or marked no-show, room charges are posted, and the drawer balances"]'::jsonb,'["Solo la cafetera", "Nada", "Solo la tele", "Que las llegadas estén registradas o como no-show, cargos aplicados y caja cuadrada"]'::jsonb,3,'A pre-close checklist prevents errors.','Evita errores.','general hospitality best practice',array['gm','night_audit']::text[],'role','med',array['audit','gm','night_audit']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
